/* MITM Solver for Noisier CRC Challenge
 * 
 * Strategy: 4 groups of 8 queries each (32 total).
 * Enumerate 13^8 ≈ 815M combos per group using fast GF(2) polynomial ops.
 * Then use meet-in-the-middle to find the consistent combination.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

// We'll represent GF(2) polynomials as arrays of 64-bit words
// 512 bits = 8 words, but we need up to degree 544 for intermediate results
#define MAX_WORDS 10  // 640 bits

typedef struct {
    uint64_t w[MAX_WORDS];
    int deg;  // degree (bit_length - 1), -1 for zero
} poly_t;

// ============== Poly operations ==============

void poly_zero(poly_t *p) {
    memset(p->w, 0, sizeof(p->w));
    p->deg = -1;
}

void poly_set_int(poly_t *p, uint64_t val) {
    memset(p->w, 0, sizeof(p->w));
    p->w[0] = val;
    if (val == 0) {
        p->deg = -1;
    } else {
        p->deg = 63 - __builtin_clzll(val);
    }
}

void poly_update_deg(poly_t *p) {
    for (int i = MAX_WORDS - 1; i >= 0; i--) {
        if (p->w[i]) {
            p->deg = 64 * i + (63 - __builtin_clzll(p->w[i]));
            return;
        }
    }
    p->deg = -1;
}

void poly_add(poly_t *r, const poly_t *a, const poly_t *b) {
    for (int i = 0; i < MAX_WORDS; i++)
        r->w[i] = a->w[i] ^ b->w[i];
    poly_update_deg(r);
}

void poly_addto(poly_t *a, const poly_t *b) {
    for (int i = 0; i < MAX_WORDS; i++)
        a->w[i] ^= b->w[i];
    poly_update_deg(a);
}

void poly_shift_left(poly_t *r, const poly_t *a, int bits) {
    int word_shift = bits / 64;
    int bit_shift = bits % 64;
    memset(r->w, 0, sizeof(r->w));

    for (int i = 0; i < MAX_WORDS - word_shift; i++) {
        r->w[i + word_shift] |= a->w[i] << bit_shift;
        if (bit_shift && i + word_shift + 1 < MAX_WORDS)
            r->w[i + word_shift + 1] |= a->w[i] >> (64 - bit_shift);
    }
    poly_update_deg(r);
}

void poly_mul(poly_t *r, const poly_t *a, const poly_t *b) {
    poly_zero(r);
    for (int i = 0; i < MAX_WORDS; i++) {
        uint64_t ai = a->w[i];
        while (ai) {
            int bit = __builtin_ctzll(ai);
            int pos = 64 * i + bit;
            poly_t shifted;
            poly_shift_left(&shifted, b, pos);
            poly_addto(r, &shifted);
            ai &= ai - 1;  // Clear lowest set bit
        }
    }
}

void poly_mod(poly_t *r, const poly_t *a, const poly_t *mod) {
    if (a->deg < mod->deg) {
        *r = *a;
        return;
    }
    *r = *a;
    for (int i = a->deg - mod->deg; i >= 0; i--) {
        if (r->deg >= mod->deg + i) {
            // Check if bit (mod->deg + i) is set
            int word_idx = (mod->deg + i) / 64;
            int bit_idx = (mod->deg + i) % 64;
            if ((r->w[word_idx] >> bit_idx) & 1) {
                poly_t shifted;
                poly_shift_left(&shifted, mod, i);
                poly_addto(r, &shifted);
            }
        }
    }
}

void poly_inv(poly_t *r, const poly_t *a, const poly_t *mod) {
    // Extended Euclidean algorithm
    poly_t r0, r1, s0, s1;
    r0 = *mod;
    r1 = *a;
    poly_zero(&s0);
    poly_set_int(&s1, 1);

    while (r1.deg >= 0) {
        poly_t q, tmp;
        // Division: q = r0 / r1, r = r0 % r1
        poly_t rem;
        rem = r0;
        poly_zero(&q);
        for (int i = r0.deg - r1.deg; i >= 0; i--) {
            int word_idx = (r1.deg + i) / 64;
            int bit_idx = (r1.deg + i) % 64;
            if (word_idx < MAX_WORDS && ((rem.w[word_idx] >> bit_idx) & 1)) {
                poly_t shifted;
                poly_shift_left(&shifted, &r1, i);
                poly_addto(&rem, &shifted);
                // Set bit i in q
                q.w[i / 64] |= (1ULL << (i % 64));
            }
        }
        poly_update_deg(&q);

        // r0, r1 = r1, rem
        tmp = r0; r0 = r1; r1 = rem;
        // s0, s1 = s1, s0 + q*s1
        poly_t qs1, new_s1;
        poly_mul(&qs1, &q, &s1);
        poly_add(&new_s1, &s0, &qs1);
        tmp = s0; s0 = s1; s1 = new_s1;
    }
    *r = s0;
}

// ============== CRT ==============

void crt_step(poly_t *result, poly_t *M, 
              const poly_t *a, const poly_t *M_cur,
              const poly_t *b, const poly_t *p) {
    // Combine a (mod M_cur) and b (mod p)
    // inv = M_cur^{-1} mod p
    poly_t M_mod_p, inv, diff, t, tM;

    poly_mod(&M_mod_p, M_cur, p);
    poly_inv(&inv, &M_mod_p, p);

    // diff = (b - a) mod p
    poly_t a_mod_p;
    poly_mod(&a_mod_p, a, p);
    poly_add(&diff, b, &a_mod_p);  // XOR = add in GF(2)
    poly_mod(&diff, &diff, p);

    // t = diff * inv mod p
    poly_mul(&t, &diff, &inv);
    poly_mod(&t, &t, p);

    // result = a + t * M_cur
    poly_mul(&tM, &t, M_cur);
    poly_add(result, a, &tM);

    // M = M_cur * p
    poly_mul(M, M_cur, p);
}

// ============== Main ==============

// This is a simplified test - full implementation would be much longer
int main() {
    printf("MITM solver for noisier CRC\n");
    printf("This is a placeholder - full implementation needed\n");
    return 0;
}

