"""
Soft EM algorithm: maintain probabilities for each candidate, 
iteratively update based on consistency with estimated key.
"""

import json, time, math, random
import numpy as np
from hashlib import sha256
from Crypto.Cipher import AES

def crc16(msg, gp):
    m = msg << 16
    for i in range(msg.bit_length()-1, -1, -1):
        if (m >> (i+16)) & 1:
            m ^= (gp << i)
    return m

def gauss_solve_gf2(A, b):
    """Solve Ax=b over GF(2). Returns x or None."""
    m, n = A.shape
    M = np.hstack([A.copy(), b.reshape(-1,1)]).astype(np.uint8)
    row = 0
    pivot_cols = []
    for col in range(n):
        pivot = None
        for r in range(row, m):
            if M[r, col]:
                pivot = r
                break
        if pivot is not None:
            if pivot != row:
                M[[row, pivot]] = M[[pivot, row]]
            pivot_cols.append(col)
            for r in range(m):
                if r != row and M[r, col]:
                    M[r] ^= M[row]
            row += 1
    # Check consistency
    for r in range(row, m):
        if M[r, n] and not np.any(M[r, :n]):
            return None
    # Extract solution (set free vars to 0)
    x = np.zeros(n, dtype=np.uint8)
    for c in pivot_cols:
        r = np.where(M[:, c])[0][0]
        x[c] = M[r, n]
    return x

def main():
    with open('/home/kou/Documents/mcparrot/playground/server_data.json') as f:
        data = json.load(f)

    responses = data['responses']
    N = len(responses)

    # Precompute CRC matrices (row format)
    print("[*] Precomputing CRC matrices...")
    all_rows = []
    for resp in responses:
        rows = [[] for _ in range(16)]
        for j in range(512):
            c = crc16(1<<j, resp['poly'])
            for b in range(16):
                if (c>>b)&1:
                    rows[b].append(j)
        all_rows.append(rows)

    # Initialize probabilities uniformly
    probs = []
    for resp in responses:
        p = [1.0/13] * 13
        probs.append(p)

    key = random.getrandbits(512)

    for iteration in range(200):
        # M-step: Build weighted linear system
        # For each query, we have 13 candidate equations, each weighted by prob

        # Build a system using the most likely candidate from each query
        selected = []
        for i, (resp, p) in enumerate(zip(responses, probs)):
            best_j = max(range(13), key=lambda j: p[j])
            selected.append(resp['candidates'][best_j])

        # Solve linear system
        A = np.zeros((N*16, 512), dtype=np.uint8)
        b = np.zeros(N*16, dtype=np.uint8)
        for i, (resp, cv) in enumerate(zip(responses, selected)):
            for bit_b in range(16):
                row = i*16 + bit_b
                for j in all_rows[i][bit_b]:
                    A[row, j] = 1
                b[row] = (cv >> bit_b) & 1

        result = gauss_solve_gf2(A, b)

        if result is not None:
            new_key = 0
            for j in range(512):
                if result[j]:
                    new_key |= (1<<j)
            key = new_key

        # E-step: Update probabilities based on CRC distances
        for i, resp in enumerate(responses):
            crc_true = crc16(key, resp['poly'])
            weights = []
            for cv in resp['candidates']:
                dist = bin(crc_true ^ cv).count('1')
                # Exponential weighting: closer = higher weight
                w = math.exp(-dist * 2.0)  # temperature factor
                weights.append(w)
            total = sum(weights)
            if total > 0:
                probs[i] = [w/total for w in weights]
            else:
                probs[i] = [1.0/13] * 13

        # Check convergence
        matches = sum(1 for i, resp in enumerate(responses) 
                      if crc16(key, resp['poly']) in resp['candidates'])

        if iteration % 10 == 0:
            print(f"  Iter {iteration}: {matches}/{N} matches")

        if matches == N:
            print(f"[+] All queries satisfied at iteration {iteration}!")
            break

    # Final check
    matches = sum(1 for resp in responses if crc16(key, resp['poly']) in resp['candidates'])
    print(f"[*] Final: {matches}/{N}")

    if matches == N:
        print(f"[*] Key: {hex(key)}")
        ak = sha256(key.to_bytes(64,'big')).digest()[:16]
        cipher = AES.new(ak, AES.MODE_CTR, nonce=b"12345678")
        flag = cipher.decrypt(bytes.fromhex(data['enc_flag_hex']))
        print(f"[+] FLAG: {flag}")

if __name__ == "__main__":
    main()

