// Polynomial mod for small degrees
static inline uint64_t poly_mod(uint64_t a, uint64_t mod) {
    int da = a ? 63 - __builtin_clzll(a) : -1;
    int dm = 63 - __builtin_clzll(mod);
    if (da < dm) return a;
    uint64_t r = a;
    for (int i = da - dm; i >= 0; i--)
        if ((r >> (i + dm)) & 1)
